#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Threading;using System.Windows;using System.Windows.Controls;using System.Windows.Controls.Primitives;
namespace FileCompass {
 internal static class FileContextTests {
  static void DrawElement(FrameworkElement element,string path,double scale){element.UpdateLayout();var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap((int)Math.Ceiling(element.ActualWidth*scale),(int)Math.Ceiling(element.ActualHeight*scale),96*scale,96*scale,System.Windows.Media.PixelFormats.Pbgra32);var visual=new System.Windows.Media.DrawingVisual();using(var dc=visual.RenderOpen())dc.DrawRectangle(new System.Windows.Media.VisualBrush(element),null,new Rect(0,0,element.ActualWidth,element.ActualHeight));bitmap.Render(visual);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using(var stream=File.Create(path))encoder.Save(stream);}
  static void WaitNative(System.Threading.Tasks.Task task){var clock=System.Diagnostics.Stopwatch.StartNew();while(!task.IsCompleted&&clock.Elapsed.TotalSeconds<55){System.Windows.Threading.Dispatcher.CurrentDispatcher.Invoke(System.Windows.Threading.DispatcherPriority.Background,new Action(delegate{}));Thread.Sleep(1);}if(!task.IsCompleted)throw new TimeoutException("Shell menu worker timed out");task.GetAwaiter().GetResult();}
  internal static int Run(string root){Directory.CreateDirectory(root);var checks=new List<string>();MainWindow window=null;Application testApp=Application.Current??new Application();Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);checks.Add(label);};try{
   SynchronizationContext.SetSynchronizationContext(new System.Windows.Threading.DispatcherSynchronizationContext(System.Windows.Threading.Dispatcher.CurrentDispatcher));FluentTheme.Ensure();ShellMenuWorker.ExecutableForTests=Environment.GetEnvironmentVariable("FILECOMPASS_SHELL_TEST_EXE");
   var locations=CommonLocations.Read();check(locations.Length>=6,"Windows known folders populate the common locations");check(locations.Select(x=>x.LocationKey).Distinct().Count()==locations.Length,"Locations have unique semantic labels");check(locations.All(x=>x.IsLocation&&x.Icon!=null&&Path.IsPathRooted(x.Root)),"Locations use actual redirected Windows paths and folder icons");check(locations.Any(x=>x.LocationKey=="locations.downloads"),"Downloads uses its Windows known-folder identity");
   var choices=new[]{new DriveChoice(@"C:\"),new DriveChoice(@"C:\Users\Demo","locations.profile"),new DriveChoice(@"C:\Users\Demo\Documents","locations.documents")};check(CommonLocations.Match(choices,@"C:\Users\Demo\Documents\Work")==choices[2],"Longest matching common folder is selected");check(CommonLocations.Match(choices,@"C:\Users\Demo2")==choices[0],"Common folder matching respects path boundaries");
   check(!FilePanel.IsContextHold(TimeSpan.FromMilliseconds(599),false),"Short right click is a selection gesture");check(FilePanel.IsContextHold(TimeSpan.FromMilliseconds(600),false),"Hold selects the program menu at threshold");check(!FilePanel.IsContextHold(TimeSpan.FromSeconds(2),true),"Right drag never opens either menu");
   string data=Path.Combine(root,"Demo"),other=Path.Combine(root,"Other");Directory.CreateDirectory(data);Directory.CreateDirectory(other);Directory.CreateDirectory(Path.Combine(data,"Photos"));File.WriteAllText(Path.Combine(data,"Readme.txt"),"Example");File.WriteAllText(Path.Combine(data,"Český název.txt"),"Example");File.WriteAllText(Path.Combine(data,"Example.zip"),"demonstration placeholder");
   check(ShellFileMenu.Compatible(new[]{Path.Combine(data,"Readme.txt"),Path.Combine(data,"Photos")}),"Native menu accepts files and folders in the same directory");check(!ShellFileMenu.Compatible(new[]{Path.Combine(data,"Readme.txt"),Path.Combine(other,"Else.txt")}),"Native menu rejects mixed-parent selections");check(!ShellFileMenu.Compatible(new string[0]),"Empty native selection is rejected");
   window=new MainWindow(data,new ProgramSettings{AutoRefresh=false}){Left=-18000,Top=-18000,ShowInTaskbar=false,ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual};window.Show();NavigationTests.WaitPanels(window);var panel=FluentUiTests.Children<FilePanel>(window).First();NavigationTests.Wait(panel.DriveDiscovery);
   var combo=(ComboBox)typeof(FilePanel).GetField("driveSelector",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(panel);check(combo.Items.Cast<DriveChoice>().Count(x=>x.IsLocation)>=6,"Locations selector includes common folders");check(combo.Items.Cast<DriveChoice>().All(x=>x.IsLocation),"Locations selector never duplicates the drive buttons");
   int resolverCalls=0;panel.DriveFolderResolver=value=>{resolverCalls++;return other;};var demo=new DriveChoice(data,"locations.documents");combo.Items.Add(demo);panel.Navigate(other,false);NavigationTests.Wait(panel.NavigationTask);combo.SelectedItem=demo;NavigationTests.Wait(panel.NavigationTask);check(panel.CurrentPath==data&&resolverCalls==0,"Common folder selection bypasses drive last-folder resolution");
   var files=panel.List.Items.Cast<Entry>().ToArray();File.WriteAllLines(Path.Combine(root,"files-debug.txt"),files.Select(x=>x.Name+" | "+x.FullPath));Entry readme=files.First(x=>Path.GetFileName(x.FullPath)=="Readme.txt"),unicode=files.First(x=>Path.GetFileName(x.FullPath)=="Český název.txt"),folder=files.First(x=>Path.GetFileName(x.FullPath)=="Photos");readme.IsMarked=unicode.IsMarked=true;panel.SelectContextEntry(readme);check(panel.Selected().Count==2,"Right click preserves an existing marked selection");panel.SelectContextEntry(folder);check(panel.Selected().Count==1&&panel.Selected()[0]==folder,"Right click outside selection targets the clicked item");
   foreach(bool windows in new[]{false,true}){panel.ApplySelectionMode(windows);panel.MarkAll(false);panel.ToggleMark(readme);panel.BeginContextEntry(unicode,new Point(15,15));panel.FinishContextEntry(TimeSpan.FromMilliseconds(100));check(readme.IsMarked&&unicode.IsMarked&&!panel.List.ContextMenu.IsOpen,"Short right click adds a mark without clearing the group or showing a menu, Windows mode "+windows);panel.BeginContextEntry(readme,new Point(15,15));panel.FinishContextEntry(TimeSpan.FromMilliseconds(100));check(!readme.IsMarked&&unicode.IsMarked,"Short right click unmarks only its target, Windows mode "+windows);panel.BeginContextEntry(folder,new Point(15,15));panel.CancelFileContextGesture();check(unicode.IsMarked&&!folder.IsMarked,"Cancelled press leaves marks intact, Windows mode "+windows);panel.BeginRightMark(readme);panel.ContinueRightMark(folder);panel.EndRightMark();check(readme.IsMarked&&folder.IsMarked,"Right dragging marks ranges in Windows mode "+windows);}panel.ApplySelectionMode(false);panel.MarkAll(false);panel.BeginContextEntry(readme,new Point(15,15));panel.AdvanceRightHold(TimeSpan.FromMilliseconds(200),true);check(!panel.RightHoldIndicatorOpen,"Short press does not display the delayed indicator");panel.AdvanceRightHold(TimeSpan.FromMilliseconds(425),true);check(panel.RightHoldIndicatorOpen&&panel.RightHoldDescription==L.Text("context.programMenu"),"Long press displays feedback describing the program menu");panel.AdvanceRightHold(TimeSpan.FromMilliseconds(600),true);check(panel.List.ContextMenu.IsOpen&&!panel.RightHoldIndicatorOpen,"Long hold opens File Compass menu, not the native Windows menu");panel.FinishContextEntry(TimeSpan.FromMilliseconds(650));check(!readme.IsMarked,"Releasing after the context menu does not toggle the file mark");check(panel.List.ContextMenu.Items.OfType<MenuItem>().Last().Tag as string=="context.windows","Windows menu remains the final command in the program menu");panel.List.ContextMenu.IsOpen=false;panel.SelectContextEntry(folder);
   var menu=panel.List.ContextMenu;menu.RaiseEvent(new RoutedEventArgs(ContextMenu.OpenedEvent));Func<string,MenuItem> command=key=>menu.Items.OfType<MenuItem>().First(x=>Convert.ToString(x.Tag)==key);check(!command("context.preview").IsEnabled&&!command("action.edit").IsEnabled,"Folder context disables file-only preview and editing");check(command("action.copy").IsEnabled&&command("action.compress").IsEnabled,"Folder context offers copying and compression");
   panel.SelectContextEntry(readme);menu.RaiseEvent(new RoutedEventArgs(ContextMenu.OpenedEvent));check(command("context.preview").IsEnabled&&command("action.edit").IsEnabled,"Single file context offers preview and edit");check(!command("action.extract").IsEnabled,"Ordinary text file does not offer active archive extraction");check(menu.Items.OfType<MenuItem>().Any(x=>Convert.ToString(x.Header)==L.Text("context.more")),"Less frequent commands are grouped in a submenu");check(panel.CanShowWindowsMenu,"Local file selection supports native Windows menu");
   var nativeFiles=ShellMenuWorker.Show(window,new[]{readme.FullPath,unicode.FullPath},true);WaitNative(nativeFiles);check(nativeFiles.Result>0,"Actual Windows shell builds a multi-file Unicode menu without invoking a command");var nativeFolder=ShellMenuWorker.Show(window,new[]{folder.FullPath},true);WaitNative(nativeFolder);check(nativeFolder.Result>0,"Actual Windows shell builds a directory menu without invoking a command");
   panel.ShowFileContextMenu(false);NavigationTests.Wait(System.Threading.Tasks.Task.Delay(80));check(menu.IsOpen,"Application menu opens programmatically");DrawElement(menu,Path.Combine(root,"file-menu.png"),1);menu.IsOpen=false;
   combo.IsDropDownOpen=true;NavigationTests.Wait(System.Threading.Tasks.Task.Delay(80));var popup=(Popup)combo.Template.FindName("PART_Popup",combo);DrawElement((FrameworkElement)popup.Child,Path.Combine(root,"locations.png"),1);combo.IsDropDownOpen=false;
   window.Close();window=null;File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"PASS: "+checks.Count}));return 0;
  }catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"FAIL: "+ex}));return 1;}finally{if(window!=null)window.Close();testApp.Shutdown();}}
 }
}
#endif
